import math
import unittest

from solution import central_measure


class CentralMeasureTests(unittest.TestCase):
    def test_odd_and_even_lengths(self):
        self.assertEqual(central_measure([9, 1, 5]), 5)
        self.assertEqual(central_measure([10, 2, 4, 8]), 6.0)
        self.assertEqual(central_measure([7]), 7)

    def test_negative_duplicate_and_mixed_numeric_values(self):
        self.assertEqual(central_measure([-2, 4, -2, 10]), 1.0)
        self.assertEqual(central_measure([1, 2.5, 3]), 2.5)

    def test_input_order_is_not_mutated(self):
        values = [8, 1, 6, 3]
        original = values[:]
        self.assertEqual(central_measure(values), 4.5)
        self.assertEqual(values, original)

    def test_empty_and_non_list_inputs(self):
        with self.assertRaises(ValueError):
            central_measure([])
        for values in [(1, 2), "12", None, {1, 2}]:
            with self.subTest(values=values), self.assertRaises(TypeError):
                central_measure(values)

    def test_non_real_and_boolean_elements(self):
        for values in [[1, True], [1, "2"], [1, None], [1, 2 + 0j]]:
            with self.subTest(values=values), self.assertRaises(TypeError):
                central_measure(values)

    def test_non_finite_elements(self):
        for value in [math.inf, -math.inf, math.nan]:
            values = [1.0, value]
            original = values[:]
            with self.subTest(value=value), self.assertRaises(ValueError):
                central_measure(values)
            self.assertEqual(len(values), len(original))
            self.assertEqual(values[0], original[0])
            if math.isnan(value):
                self.assertTrue(math.isnan(values[1]))
            else:
                self.assertEqual(values[1], original[1])


if __name__ == "__main__":
    unittest.main()

